// Builds dist/data/melee.js: the quick melee attack every Helldiver has and the bayonet some
// weapons carry (db/source/wiki_melee.json, scripts/fetch-melee.mjs). A weapon has the bayonet
// when its wiki page shows the Melee_Bayonet attack data (db/source/wiki_pages.json). Do not edit the output.
// Usage: node scripts/build-melee.mjs
import { readFile, writeFile } from 'node:fs/promises';
import { personalWeapons } from '../dist/data/personal-weapons.js';

const read = async name => JSON.parse(await readFile(new URL(`../db/source/${name}`, import.meta.url), 'utf8'));
const attack = record => ({ damage: record.dmg, durable: record.dmg2, ap: record.ap1, demolition: record.demo, stagger: record.stun, push: record.push });

export async function buildMelee() {
  const melee = await read('wiki_melee.json');
  const pages = (await read('wiki_pages.json')).pages;
  const byTitle = new Map(personalWeapons.map(weapon => [weapon.en, weapon.id]));
  const bayonet = Object.entries(pages)
    .filter(([, page]) => /Attack[ _]Data\/attack\|damage\|Melee_Bayonet/.test(page?.wikitext ?? ''))
    .map(([title]) => { if (!byTitle.has(title)) throw new Error(`${title} shows the bayonet but is not in personal-weapons.js`); return byTitle.get(title); })
    .sort();
  return { source: { page: melee.source, revision: melee.revision }, helldiver: attack(melee.attacks.Melee_Helldiver), bayonet: attack(melee.attacks.Melee_Bayonet), bayonetWeapons: bayonet };
}

if (import.meta.url === `file:///${process.argv[1].replaceAll('\\', '/').replace(/^\//, '')}`) {
  const data = await buildMelee();
  await writeFile(new URL('../dist/data/melee.js', import.meta.url), `// Generated by scripts/build-melee.mjs from the Helldivers Wiki datamine (CC BY-NC-SA 4.0). Do not edit.
// Quick melee: every Helldiver's default strike, and the bayonet of the weapons in bayonetWeapons.
export const meleeSource = ${JSON.stringify(data.source)};
export const quickMelee = ${JSON.stringify({ helldiver: data.helldiver, bayonet: data.bayonet })};
export const bayonetWeapons = ${JSON.stringify(data.bayonetWeapons)};
`);
  console.log(`quick melee ${data.helldiver.damage}, bayonet ${data.bayonet.damage} on ${data.bayonetWeapons.join(', ')}`);
}
